import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_CUDA_SRC = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <cuda_bf16.h>
#include <float.h>

__device__ __forceinline__ void combine_online(float &m, float &s, float m2, float s2) {
    float mn = fmaxf(m, m2);
    s = s * __expf(m - mn) + s2 * __expf(m2 - mn);
    m = mn;
}

template <typename scalar_t, int WARPS_PER_BLOCK>
__global__ void softmax_warp_rows_kernel(const scalar_t* __restrict__ x,
                                         scalar_t* __restrict__ y,
                                         int N, int D) {
    int tid = threadIdx.x;
    int lane = tid & 31;
    int warp = tid >> 5;
    int row = blockIdx.x * WARPS_PER_BLOCK + warp;
    if (row >= N) return;

    const scalar_t* __restrict__ row_x = x + (long long)row * D;
    scalar_t* __restrict__ row_y = y + (long long)row * D;

    float m = -FLT_MAX;
    float s = 0.0f;

    #pragma unroll 1
    for (int col = lane; col < D; col += 32) {
        float v = static_cast<float>(row_x[col]);
        float mn = fmaxf(m, v);
        s = s * __expf(m - mn) + __expf(v - mn);
        m = mn;
    }

    #pragma unroll
    for (int off = 16; off > 0; off >>= 1) {
        float pm = __shfl_xor_sync(0xffffffff, m, off);
        float ps = __shfl_xor_sync(0xffffffff, s, off);
        combine_online(m, s, pm, ps);
    }

    float inv_s = 1.0f / s;
    #pragma unroll 1
    for (int col = lane; col < D; col += 32) {
        float v = static_cast<float>(row_x[col]);
        row_y[col] = static_cast<scalar_t>(__expf(v - m) * inv_s);
    }
}

template <typename scalar_t, int BLOCK_THREADS>
__global__ void softmax_block_rows_kernel(const scalar_t* __restrict__ x,
                                          scalar_t* __restrict__ y,
                                          int N, int D) {
    int row = blockIdx.x;
    if (row >= N) return;
    int tid = threadIdx.x;
    const scalar_t* __restrict__ row_x = x + (long long)row * D;
    scalar_t* __restrict__ row_y = y + (long long)row * D;

    float m = -FLT_MAX;
    float s = 0.0f;
    #pragma unroll 1
    for (int col = tid; col < D; col += BLOCK_THREADS) {
        float v = static_cast<float>(row_x[col]);
        float mn = fmaxf(m, v);
        s = s * __expf(m - mn) + __expf(v - mn);
        m = mn;
    }

    __shared__ float smem_m[BLOCK_THREADS];
    __shared__ float smem_s[BLOCK_THREADS];
    smem_m[tid] = m;
    smem_s[tid] = s;
    __syncthreads();

    for (int stride = BLOCK_THREADS >> 1; stride >= 32; stride >>= 1) {
        if (tid < stride) {
            float m2 = smem_m[tid + stride];
            float s2 = smem_s[tid + stride];
            combine_online(m, s, m2, s2);
            smem_m[tid] = m;
            smem_s[tid] = s;
        }
        __syncthreads();
    }

    if (tid < 32) {
        m = smem_m[tid];
        s = smem_s[tid];
        #pragma unroll
        for (int off = 16; off > 0; off >>= 1) {
            float pm = __shfl_xor_sync(0xffffffff, m, off);
            float ps = __shfl_xor_sync(0xffffffff, s, off);
            combine_online(m, s, pm, ps);
        }
    }
    // Broadcast the row max/sum through shared memory.
    if (tid == 0) {
        smem_m[0] = m;
        smem_s[0] = s;
    }
    __syncthreads();
    m = smem_m[0];
    s = smem_s[0];
    float inv_s = 1.0f / s;

    #pragma unroll 1
    for (int col = tid; col < D; col += BLOCK_THREADS) {
        float v = static_cast<float>(row_x[col]);
        row_y[col] = static_cast<scalar_t>(__expf(v - m) * inv_s);
